async function a(t,n,e){let r=new Array(t.length),s=Math.max(1,Math.min(Math.floor(n),t.length)),u=0,i=async()=>{for(;;){let o=u;if(u+=1,o>=t.length)return;r[o]=await e(t[o],o)}};return await Promise.all(Array.from({length:s},i)),r}function p(t){return t.reduce((n,e)=>({input_tokens:n.input_tokens+e.input_tokens,output_tokens:n.output_tokens+e.output_tokens}),{input_tokens:0,output_tokens:0})}export{a,p as b};
